<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/config.php';require_once BASE_PATH.'/shared/marketing.php';marketing_require_access();
$ctx=marketing_phase3_context($_GET);$report=(string)($_GET['report']??'monthly');$name='marketing-'.$report.'-'.$ctx['period']['from'].'-'.$ctx['period']['to'].'.csv';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$name.'"');$out=fopen('php://output','wb');fputcsv($out,['Marketing report',$ctx['period']['label'],$ctx['period']['from'],$ctx['period']['to']]);
if($report==='attribution'){fputcsv($out,['Order','Date','Customer','Order Total','Source','Campaign','Attribution Method']);foreach($ctx['attributions']as$a)fputcsv($out,[$a['order_number'],$a['order_date'],$a['customer_name'],$a['total_amount'],$a['source_label'],$a['campaign_name'],$a['attribution_method']]);}
else{fputcsv($out,['Metric','Value','Source']);foreach([['Content Published',$ctx['summary']['content_published'],'Marketing workspace'],['Campaigns Active',$ctx['summary']['campaigns_active'],'Marketing workspace'],['Ad Spend',$ctx['summary']['spend'],'Manual / imported snapshots'],['Reach',$ctx['summary']['reach'],'Performance snapshots'],['Engagements',$ctx['summary']['engagements'],'Performance snapshots'],['Clicks',$ctx['summary']['clicks'],'Performance snapshots'],['Orders Attributed',$ctx['summary']['orders_attributed'],'Portal Orders'],['Revenue Attributed',$ctx['summary']['revenue_attributed'],'Portal Orders'],['ROAS',$ctx['summary']['roas'],'Portal Orders + ad spend']]as$row)fputcsv($out,$row);fputcsv($out,[]);fputcsv($out,['Top Content','Platform','Reach','Engagements','Saves','Shares','Clicks']);foreach($ctx['top']as$t)fputcsv($out,[$t['title'],$t['platform'],$t['reach'],$t['engagements'],$t['saves'],$t['shares'],$t['clicks']]);}
marketing_phase3_audit('report_generated','report',0,$report.' '.$ctx['period']['from'].' to '.$ctx['period']['to']);fclose($out);
